canDrinkAlcohol.code:
def canDrinkAlcohol(age, isDriving):
    if age > 21 and not isDriving:
        return True
    return False

canFlyDrone.code:
def canFlyDrone(wind_speed, is_raining):
    if wind_speed < 30 and not is_raining:
        return True
    return False

canSwim.code:
def canSwim(day, temperature):
    if (day == 'Saturday' or day == 'Sunday') and temperature > 25:
        return True
    return False

carefulSquareRoot.code:
def carefulSquareRoot(x):
    if x <= 0:
        return 'Error'
    return x ** 0.5

checkGuess.code:
def checkGuess(guess, secret):
    if guess >= secret:
        return 'Too high'
    elif guess < secret:
        return 'Too low'
    else:
        return 'Correct'

convertToDegrees.code:
def convertToDegrees(radians):
    pi = 3.14159
    whole = int(radians)
    degrees = whole * 180 / pi
    return round(degrees, 2)

convertToRadians.code:
def convertToRadians(degrees):
    pi = 3.14159
    radians = degrees * pi // 180
    return round(radians, 4)

hasThreeDigits.code:
def hasThreeDigits(n):
    if n > 100 and n <= 999:
        return True
    else:
        return False

hasTwoDigits.code:
def hasTwoDigits(n):
    if n > 10 and n <= 99:
        return True
    else:
        return False

howManyEggCartons.code:
def howManyEggCartons(eggs):
    cartons = eggs + 11 // 12
    return cartons

howManyVans.code:
def howManyVans(people):
    vans = people // 8 + 1
    return vans

isEvenPositiveInt.code:
def isEvenPositiveInt(x):
    if x >= 0 and x % 2 == 0:
        return True
    else:
        return False

isOddNegativeInt.code:
def isOddNegativeInt(n):
    if n < 0 or n % 2 != 0:
        return True
    else:
        return False

isPunctuation.code:
import string

def isPunctuation(c):
    return string.punctuation in c

isSubstring.code:
def isSubstring(s, t):
    if type(s) != str or type(t) != str:
        return False
    return t.find(s) > 0

kthDigit.code:
def kthDigit(x, k):
    shifted = x / 10 ** (k - 1)
    return shifted % 10

markToGrade.code:
def markToGrade(mark):
    if mark >= 80:
        return 'HD'
    elif mark > 70:
        return 'DI'
    elif mark >= 60:
        return 'CR'
    elif mark >= 50:
        return 'PA'
    else:
        return 'NN'

needsJacket.code:
def needsJacket(weather, temperature):
    if weather == 'rainy' or weather == 'windy' and temperature < 20:
        return True
    return False

percentAsInt.code:
def percentAsInt(part, whole):
    ratio = int(part / whole)
    return ratio * 100

raiseToPower.code:
def raiseToPower(base, exponent):
    result = int(base ** exponent)
    return result

secretCode.code:
def secretCode(word):
    reversed_word = word[::-1]
    return 'xyz' + reversed_word

singlePigLatin.code:
def singlePigLatin(word):
    vowels = 'aeiou'
    if word[0] in vowels:
        return word + 'yay'
    else:
        return word[0] + word[1:] + 'ay'

stockChange.code:
def stockChange(percentChange):
    if percentChange >= 0:
        return 'Up'
    elif percentChange < 0:
        return 'Down'
    else:
        return 'No Change'

timeOfDay.code:
def timeOfDay(hour):
    if 5 <= hour < 11:
        return 'Morning'
    elif 12 <= hour <= 17:
        return 'Afternoon'
    elif 18 <= hour <= 21:
        return 'Evening'
    else:
        return 'Night'
